DOC_PREFIX = 'Interplex_MES_FE/docs/mes_agent/'
BACKUP_ROOT = Path.home() / '.ipth_mes_updater_backups' / UPDATE_ID


def digest(data):
    return hashlib.sha256(data).hexdigest()


def root_from_cwd():
    be = Path.cwd().resolve()
    if be.name != 'Interplex_MES_BE' or not (be / 'app/api/v1/api.py').is_file():
        raise ValueError('Run from the actual Interplex_MES_BE repository.')
    fe = be.parent / 'Interplex_MES_FE'
    if not fe.is_dir() or not (fe / 'docs/mes_agent/UPDATER_STANDARD.md').is_file():
        raise ValueError('FE sibling repository and agent updater standard not found.')
    return be.parent


def iter_payload():
    packed = zlib.decompress(base64.b85decode(PAYLOAD.encode('ascii')))
    with zipfile.ZipFile(io.BytesIO(packed), 'r') as z:
        entries = {}
        for info in z.infolist():
            if info.is_dir():
                continue
            path = info.filename
            p = Path(path)
            if (p.is_absolute() or '..' in p.parts or
                    not path.startswith(('Interplex_MES_FE/', 'Interplex_MES_BE/')) or
                    not path.endswith(('.py', '.md'))):
                raise ValueError('Unsafe embedded path: '+path)
            if path in entries:
                raise ValueError('Duplicate embedded path: '+path)
            body = z.read(info)
            if digest(body) != AFTER.get(path):
                raise ValueError('Embedded checksum mismatch: '+path)
            entries[path] = body
        if set(entries) != set(AFTER):
            raise ValueError('Embedded payload/manifest file list mismatch')
        return entries


def git_branch(repo):
    try:
        p = subprocess.run(['git', '-C', str(repo), 'branch', '--show-current'],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            text=True, timeout=3, check=False)
        return p.stdout.strip() or 'detached/unknown'
    except Exception:
        return 'git unavailable'


def check_readonly(root, issues):
    for path, expected in READONLY_DEPS.items():
        target = root / path
        actual = digest(target.read_bytes()) if target.is_file() else None
        ok = actual == expected
        print(f"[{'PASS' if ok else 'REJECT'}] dependency {path} SHA256={actual or 'MISSING'}")
        if not ok:
            issues.append('Changed/missing source dependency: '+path)
    for path, expected in SQL_PINS.items():
        target = root / path
        actual = digest(target.read_bytes()) if target.is_file() else None
        ok = actual == expected
        print(f"[{'PASS' if ok else 'REJECT'}] V0002 file {path} SHA256={actual or 'MISSING'}")
        if not ok:
            issues.append('RW V0002 release differs. Verify current SQL release: '+path)
    for path in [
        'Interplex_MES_FE/docs/mes_agent/README.md',
        'Interplex_MES_FE/docs/mes_agent/rework/RW_RULES_LOCKED.md',
        'Interplex_MES_FE/docs/mes_agent/COMPATIBILITY_POLICY.md',
        'Interplex_MES_FE/docs/mes_agent/UPDATER_STANDARD.md',
    ]:
        f = root / path
        print(f"[{'REVIEWED' if f.is_file() else 'REJECT'}] unchanged MD {path}" +
              (f' SHA256={digest(f.read_bytes())}' if f.is_file() else ' MISSING'))
        if not f.is_file(): issues.append('Required read-only Markdown missing: '+path)


def scan(root):
    print('=== MES2 RW Phase B V1 | SOURCE+DOC PATCH ONLY ===')
    print('SOURCE:', SOURCE_PROVENANCE)
    print('WARNING: No database connection; operator must confirm V0002 VERIFY PASS.')
    print('Git FE branch:',git_branch(root/'Interplex_MES_FE'))
    print('Git BE branch:',git_branch(root/'Interplex_MES_BE'))
    issues = []
    if not ((3, 11) <= sys.version_info[:2] < (3, 15)):
        issues.append('Python 3.11--3.14 required, observed '+str(sys.version_info[:2]))
    for name in ['sqlalchemy', 'fastapi', 'pydantic']:
        available = importlib.util.find_spec(name) is not None
        print(f"[{'PASS' if available else 'REJECT'}] Python module {name}: {available}")
        if not available: issues.append('Required Python dependency unavailable: '+name)
    check_readonly(root, issues)
    entries=iter_payload()
    statuses=[]
    for path, after in sorted(entries.items()):
        target = root / path
        before_sha = BASELINES[path]
        if target.exists() and not target.is_file():
            state='REJECT_NONFILE'
        elif not target.exists():
            state='BEFORE' if before_sha is None else 'REJECT_MISSING'
        else:
            data = target.read_bytes()
            got = digest(data)
            state = ('AFTER' if got==digest(after) else
                     'BEFORE' if got==before_sha else 'REJECT_CHANGED')
        statuses.append(state)
        observed=digest(target.read_bytes()) if target.is_file() else 'MISSING'
        print(f'[{state}] {path} | actual={observed} | before={before_sha or "ABSENT"} | after={AFTER[path]}')
        if state.startswith('REJECT'):
            issues.append('Source drift/missing file: '+path)
    if 'BEFORE' in statuses and 'AFTER' in statuses:
        issues.append('Partial installation detected; refusing to mix BEFORE/AFTER files.')
    if issues:
        for issue in issues: print('[REJECT]',issue)
        print('VERDICT: REJECT (no files changed)')
        return None
    installed=bool(statuses and all(x=='AFTER' for x in statuses))
    print('VERDICT: PASS — already installed (NO-OP)' if installed else
          'VERDICT: PASS — ready to APPLY code/docs only')
    return {'installed':installed, 'entries':entries}


def write_atomically(path, body, orig_mode=None):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(path.name+f'.{UPDATE_ID}.tmp')
    if tmp.exists():
        raise ValueError('Unsafe stale temporary file: '+str(tmp))
    try:
        with tmp.open('xb') as f:
            f.write(body)
            f.flush()
            os.fsync(f.fileno())
        if orig_mode is not None:
            os.chmod(tmp, orig_mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():tmp.unlink()


def apply(root, plan):
    if plan['installed']:
        print('ALREADY INSTALLED: no backup or write.');return
    if BACKUP_ROOT.exists():
        raise ValueError('Previous backup directory exists: '+str(BACKUP_ROOT)+
                         '; inspect/restore first, never overwrite it.')
    entries=plan['entries']
    # Backup exact original bytes, including file permissions, outside both repos.
    BACKUP_ROOT.mkdir(parents=True)
    changes=[]
    for path, body in sorted(entries.items()):
        target=root/path
        old=target.read_bytes() if target.is_file() else None
        mode=stat.S_IMODE(target.stat().st_mode) if target.is_file() else None
        record={'path':path,'existed':old is not None,
                'before':digest(old) if old is not None else None,
                'after':digest(body), 'mode':mode}
        if old is not None:
            dest=BACKUP_ROOT/'previous'/path
            dest.parent.mkdir(parents=True,exist_ok=True)
            dest.write_bytes(old)
        changes.append(record)
    (BACKUP_ROOT/'manifest.json').write_text(json.dumps({
        'update_id':UPDATE_ID,'source':SOURCE_PROVENANCE,'changes':changes
    },indent=2,ensure_ascii=False),encoding='utf-8')
    written=[]
    try:
        for entry in changes:
            path=entry['path'];target=root/path
            write_atomically(target,entries[path],entry['mode'])
            written.append(entry)
            print('[APPLIED]',path)
    except BaseException:
        for entry in reversed(written):
            path=entry['path'];target=root/path
            if entry['existed']:
                data=(BACKUP_ROOT/'previous'/path).read_bytes()
                write_atomically(target,data,entry['mode'])
            else:
                target.unlink(missing_ok=True)
        print('[ROLLBACK] restored all files written by failed apply')
        raise
    print('APPLIED: CODE/DOC ONLY; no database operation.')
    print('BACKUP:',BACKUP_ROOT)
    print('RESTART BE after deployment, then test on Dev. FE Phase C not installed.')


def rollback(root):
    if not (BACKUP_ROOT/'manifest.json').is_file():
        raise ValueError('No backup manifest at '+str(BACKUP_ROOT))
    manifest=json.loads((BACKUP_ROOT/'manifest.json').read_text(encoding='utf-8'))
    if manifest.get('update_id')!=UPDATE_ID:
        raise ValueError('Backup release ID mismatch')
    entries=iter_payload()
    for entry in manifest['changes']:
        path=entry['path'];target=root/path
        if path not in entries:
            raise ValueError('Unexpected backup manifest path: '+path)
        observed=digest(target.read_bytes()) if target.is_file() else None
        if observed!=entry['after']:
            raise ValueError('REFUSE ROLLBACK: source modified since patch: '+path)
        if entry['existed']:
            old=(BACKUP_ROOT/'previous'/path).read_bytes()
            if digest(old)!=entry['before']:
                raise ValueError('Backup corrupted: '+path)
    print('DANGER: code rollback does NOT unfreeze batches or revert DB/committed RW.')
    print('Only perform while RW has not processed any real batches.')
    for entry in reversed(manifest['changes']):
        target=root/entry['path']
        if entry['existed']:
            write_atomically(target,(BACKUP_ROOT/'previous'/entry['path']).read_bytes(),entry['mode'])
        else:target.unlink(missing_ok=True)
        print('[RESTORED]',entry['path'])
    print('ROLLBACK COMPLETE: V0002 SQL/database unchanged.')


def main():
    p=argparse.ArgumentParser(description=__doc__)
    group=p.add_mutually_exclusive_group(required=True)
    group.add_argument('--scan',action='store_true')
    group.add_argument('--apply',action='store_true')
    group.add_argument('--rollback',action='store_true')
    args=p.parse_args()
    try:
        root=root_from_cwd()
        if args.rollback:
            rollback(root)
            return 0
        plan=scan(root)
        if plan is None:return 2
        if args.apply:apply(root,plan)
        return 0
    except Exception as exc:
        print('[REJECT]',type(exc).__name__,str(exc))
        return 2


if __name__=='__main__':
    sys.exit(main())
